<?php $editing = !empty($editCategory); $categoryValue = static fn(string $key, mixed $default = '') => htmlspecialchars((string) ($editCategory->$key ?? $default)); ?>
<section class="hero-row compact-hero"><div><span class="eyebrow">Organização</span><h2 class="page-heading">Categorias</h2><p class="page-subtitle">Classifique entradas e saídas para entender seus hábitos.</p></div></section>
<div class="catalog-layout"><section class="panel"><div class="panel-heading"><div><span class="eyebrow"><?= $editing ? 'Editar categoria' : 'Nova categoria' ?></span><h3><?= $editing ? 'Atualizar categoria' : 'Adicionar categoria' ?></h3></div></div><form method="post" action="<?= $editing ? '/categorias/' . (int) $editCategory->id . '/atualizar' : '/categorias' ?>" class="inline-form"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><label class="field"><span>Nome</span><input type="text" name="name" value="<?= $categoryValue('name') ?>" placeholder="Ex.: Assinaturas" maxlength="120" required></label><label class="field"><span>Tipo</span><select name="type"><option value="expense" <?= ($editCategory->type ?? 'expense') === 'expense' ? 'selected' : '' ?>>Despesa</option><option value="income" <?= ($editCategory->type ?? '') === 'income' ? 'selected' : '' ?>>Receita</option></select></label><label class="field"><span>Cor</span><input type="color" name="color" value="<?= $categoryValue('color', '#2563eb') ?>"></label><div class="form-actions"><button class="button button-primary" type="submit"><?= $editing ? 'Salvar categoria' : 'Adicionar' ?></button><?php if ($editing): ?><a class="button button-ghost" href="/categorias">Cancelar</a><?php endif; ?></div></form></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Categorias disponíveis</span><h3><?= count($categories) ?> categorias</h3></div></div><div class="catalog-list"><?php foreach ($categories as $category): ?><div class="catalog-item"><span class="category-dot" style="background:<?= htmlspecialchars($category->color) ?>"></span><div><strong><?= htmlspecialchars($category->name) ?></strong><small><?= $category->type === 'income' ? 'Receita' : 'Despesa' ?><?= $category->user_id === null ? ' · padrão' : '' ?></small></div><span class="status-badge status-<?= $category->status ?>"><?= $category->status === 'active' ? 'Ativa' : 'Inativa' ?></span><?php if ($category->user_id !== null): ?><details class="action-menu"><summary>•••</summary><div class="action-popover"><a href="/categorias?edit=<?= (int) $category->id ?>">Editar</a><form method="post" action="/categorias/<?= (int) $category->id ?>/toggle"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit"><?= $category->status === 'active' ? 'Desativar' : 'Ativar' ?></button></form><form method="post" action="/categorias/<?= (int) $category->id ?>/excluir" data-confirm="Excluir esta categoria?"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit" class="danger-text">Excluir</button></form></div></details><?php endif; ?></div><?php endforeach; ?></div></section></div>
